75	@@ -0,0 +1,190 @@
76	+//! The heap budget of a whole-project run ([`crate::resolve`] and the calls beside it, which `extract` makes).
77	+//!
78	+//! A converted type is a tree the run builds in its own heap, and a type that expands to millions of members (a style
79	+//! system declared in the project's own source, with hundreds of properties each over a hundred conditions) builds
80	+//! tens of GiB of them, most of it copies of trees the converter recalls from its memo between two requests. The budget
81	+//! is the safety net under every such shape: the run reads the heap before each component and every [`STEPS_PER_READ`]
82	+//! steps (a checker request, or a type the converter converts or recalls), and once the heap is past the budget it
83	+//! takes no further step: the conversion in flight stops at its next one. Every component it has not answered by then, the one in flight included, keeps its
84	+//! structural result, and one warning says how many and why. Which components those are depends on how far each lane
85	+//! had got, so past the budget the output depends on timing; a run that stays under it is unchanged.
86	+//!
87	+//! The heap is what mimalloc, the allocator of the CLI and of the native binding, has committed
88	+//! (`mi_process_info`): the converter's trees, its memo and the merged props, all the Rust memory of the run. It
89	+//! leaves out the checker's arenas, a range of their own that [`OnDemand`](crate::OnDemand)'s bound reads. A process
90	+//! whose allocator is not mimalloc reads only mimalloc's own small commit, and so never reaches the budget.
91	+
92	+use std::sync::OnceLock;
93	+use std::sync::atomic::{AtomicU64, Ordering};
94	+
95	+use caliper_docgen_core::types::{Diagnostic, DiagnosticCode, DiagnosticSeverity};
96	+
97	+use crate::rpc::CallError;
98	+
99	+/// The most a budget derived from the machine allows: 8 GiB, about seven times the 1.1 GiB the largest corpus measured
100	+/// commits (Mantine's core, shadcn, `gate-large`; docs/type-checker-integration.md).
101	+pub const MAX_HEAP_BUDGET: u64 = 8 << 30;
102	+
103	+/// How many steps (checker requests, and types converted or recalled from the memo) a run takes between two reads of
104	+/// the heap, besides the read before each component. A read costs about 0.9 µs (`mi_process_info`, measured over
105	+/// 100,000 reads on an M-series Mac), so a read every 32 steps is about 30 ns a step.
106	+const STEPS_PER_READ: u64 = 32;
107	+
108	+/// How large a whole-project run's heap may grow before it stops asking the checker (the module's documentation).
109	+#[derive(Debug, Clone, Copy)]
110	+pub struct HeapBudget {
111	+    bytes: u64,
112	+    meter: fn() -> u64,
113	+}
114	+
115	+impl HeapBudget {
116	+    /// The budget of this machine: half its physical memory, at most [`MAX_HEAP_BUDGET`] (that, where the memory
117	+    /// cannot be read). Half, because the heap is not all the process holds (the checker's arenas, the structural
118	+    /// result, the JSON being written, and in the binding the host's own heap), and a run past the machine's memory
119	+    /// swaps until it is killed rather than finishing.
120	+    pub fn machine() -> Self {
121	+        Self::new(physical_memory().map_or(MAX_HEAP_BUDGET, |bytes| (bytes / 2).min(MAX_HEAP_BUDGET)))
122	+    }
123	+
124	+    /// A budget of `bytes` of mimalloc's committed heap.
125	+    pub fn new(bytes: u64) -> Self {
126	+        Self { bytes, meter: committed }
127	+    }
128	+
129	+    /// A budget of `bytes` as `meter` reads the heap: tests stand in a meter whose readings they choose.
130	+    #[doc(hidden)]
131	+    pub fn metered(bytes: u64, meter: fn() -> u64) -> Self {
132	+        Self { bytes, meter }
133	+    }
134	+
135	+    /// The bytes the budget allows.
136	+    pub fn bytes(&self) -> u64 {
137	+        self.bytes
138	+    }
139	+}
140	+
141	+/// The bytes mimalloc has committed for the whole process, as it counts them.
142	+pub(crate) fn committed() -> u64 {
143	+    let mut commit = 0usize;
144	+    let null = std::ptr::null_mut();
145	+    // SAFETY: `mi_process_info` writes each out-parameter that is not null and reads nothing else; `commit` outlives
146	+    // the call.
147	+    #[allow(unsafe_code)]
148	+    unsafe {
149	+        libmimalloc_sys::mi_process_info(null, null, null, null, null, &raw mut commit, null, null);
150	+    }
151	+    commit as u64
152	+}
153	+
154	+/// The machine's physical memory in bytes.
155	+#[cfg(unix)]
156	+fn physical_memory() -> Option<u64> {
157	+    // SAFETY: `sysconf` reads a system constant and has no other effect.
158	+    #[allow(unsafe_code)]
159	+    let (pages, size) = unsafe { (libc::sysconf(libc::_SC_PHYS_PAGES), libc::sysconf(libc::_SC_PAGESIZE)) };
160	+    u64::try_from(pages).ok()?.checked_mul(u64::try_from(size).ok()?)
161	+}
162	+
163	+/// Elsewhere the machine's memory is not read.
164	+#[cfg(not(unix))]
165	+fn physical_memory() -> Option<u64> {
166	+    None
167	+}
168	+
169	+tokio::task_local! {
170	+    /// The watch of the run the current task answers for ([`step`]). A task outside a run's lanes has none, and is never
171	+    /// stopped.
172	+    pub(crate) static HEAP: std::sync::Arc<Watch>;
173	+}
174	+
175	+/// One step of the run the current task answers for: a checker request, or a type converted or recalled. Refused once
176	+/// the run's heap is past its budget.
177	+pub(crate) fn step() -> Result<(), CallError> {
178	+    match HEAP.try_with(|watch| watch.allows_step()) {
179	+        Ok(false) => Err(CallError::OverBudget),
180	+        Ok(true) | Err(_) => Ok(()),
181	+    }
182	+}
183	+
184	+/// One run's reading of its heap against its budget, shared by its lanes. Once past, it stays past.
185	+pub(crate) struct Watch {
186	+    budget: Option<HeapBudget>,
187	+    steps: AtomicU64,
188	+    peak: AtomicU64,
189	+    /// The heap the read that found it past the budget saw.
190	+    held: OnceLock<u64>,
191	+}
192	+
193	+impl Watch {
194	+    /// A watch over `budget`; with none, the run is never stopped and the heap never read.
195	+    pub(crate) fn new(budget: Option<HeapBudget>) -> Self {
196	+        Self { budget, steps: AtomicU64::new(0), peak: AtomicU64::new(0), held: OnceLock::new() }
197	+    }
198	+
199	+    /// Reads the heap; whether it is past the budget, now or before.
200	+    pub(crate) fn past(&self) -> bool {
201	+        let Some(budget) = self.budget else { return false };
202	+        if self.held.get().is_some() {
203	+            return true;
204	+        }
205	+        let held = (budget.meter)();
206	+        self.peak.fetch_max(held, Ordering::Relaxed);
207	+        if held > budget.bytes {
208	+            self.held.get_or_init(|| held);
209	+            return true;
210	+        }
211	+        false
212	+    }
213	+
214	+    /// Whether the heap was found past the budget, without reading it.
215	+    pub(crate) fn passed(&self) -> bool {
216	+        self.held.get().is_some()
217	+    }
218	+
219	+    /// Whether the run may take one more step: not once the heap is past the budget, which every [`STEPS_PER_READ`]th
220	+    /// step reads.
221	+    fn allows_step(&self) -> bool {
222	+        if self.budget.is_none() {
223	+            return true;
224	+        }
225	+        if self.passed() {
226	+            return false;
227	+        }
228	+        let taken = self.steps.fetch_add(1, Ordering::Relaxed);
229	+        !(taken.is_multiple_of(STEPS_PER_READ) && self.past())
230	+    }
231	+
232	+    /// The most the heap held at a read, in bytes; 0 when it was never read.
233	+    pub(crate) fn peak(&self) -> u64 {
234	+        self.peak.load(Ordering::Relaxed)
235	+    }
236	+
237	+    /// The one warning for the components `left` structural once the heap was past the budget; none when it never
238	+    /// was, or nothing was left.
239	+    pub(crate) fn diagnostic(&self, mut left: Vec<String>) -> Option<Diagnostic> {
240	+        let (Some(budget), Some(held)) = (self.budget, self.held.get()) else { return None };
241	+        if left.is_empty() {
242	+            return None;
243	+        }
244	+        left.sort();
245	+        let mut diagnostic = Diagnostic::new(
246	+            DiagnosticSeverity::Warning,
247	+            DiagnosticCode::SemanticBackend,
248	+            format!(
249	+                "{} component(s) kept their structural result: the heap held {} MiB, past this run's {} MiB budget, \
250	+                 so the TypeScript checker was asked nothing more. Which components the checker had answered by then \
251	+                 depends on timing, so this output can differ from run to run",
252	+                left.len(),
253	+                held >> 20,
254	+                budget.bytes >> 20
255	+            ),
256	+        )
257	+        .with_help(
258	+            "The budget is half the machine's memory, at most 8 GiB. A type that expands to millions of members, \
259	+             such as a style system declared in the project's own source, is the usual cause; `--no-checker` gives \
260	+             the structural result for every component.",
261	+        );
262	+        diagnostic.affects = left;
263	+        Some(diagnostic)
264	+    }
265	+}
