185	/// [`resolve_cached`] over the checker's program when `early` ([`start_early`]) was opened for this request (over the
186	/// root files this request has, with its options); it is dropped otherwise, and when the kept answer is used.
187	pub fn resolve_cached_early(
188	    request: SemanticRequest,
189	    cache_dir: &Utf8Path,
190	    early: Option<EarlyStart>,
191	) -> SemanticOutcome {
192	    if request.record_to.is_some() {
193	        discard(early);
194	        return resolve(request);
195	    }
196	    let file = cache_dir.join(kept::FILE);
197	    let key = kept::request_key(&request);
198	    let started = std::time::Instant::now();
199	    if let Some(outcome) = kept::load(&file, key) {
200	        discard(early);
201	        tracing::debug!(ms = started.elapsed().as_millis() as u64, "the checker's kept answer still holds");
202	        return outcome;
203	    }
204	    // The answer saved below carries what the run read: a program that did not note its reads cannot be used.
205	    let noted = early.as_ref().is_some_and(|early| early.reads.is_some());
206	    let early = fitting(early, &request, noted);
207	    let reads = early.as_ref().and_then(|early| early.reads.clone()).unwrap_or_default();
208	    let outcome = resolve_with(request, Some(reads.clone()), early);
209	    kept::save(&file, key, &reads, &outcome);
210	    outcome
211	}
