328	fn resolve_with(
329	    mut request: SemanticRequest,
330	    reads: Option<Arc<kept::Reads>>,
331	    early: Option<EarlyStart>,
332	) -> SemanticOutcome {
333	    request.heap_budget.get_or_insert_with(HeapBudget::machine);
334	    let teardown = request.teardown;
335	    if let Some(opened) = early.and_then(|early| early.handle).and_then(|handle| handle.join().ok().flatten()) {
336	        let Opened { runtime, checker, programs } = opened;
337	        let outcome = match programs {
338	            Ok(programs) => runtime.block_on(async {
339	                let files = root_files(&request);
340	                let answered = answer_opened(programs, &request, &files, std::time::Instant::now()).await;
341	                checker.shutdown().await;
342	                answered
343	            }),
344	            Err(unavailable) => {
345	                runtime.block_on(checker.shutdown());
346	                unavailable
347	            }
348	        };
349	        if teardown == Teardown::OneShot {
350	            std::mem::forget(runtime);
351	        }
352	        return outcome;
353	    }
354	    let threads = std::thread::available_parallelism().map_or(1, |count| count.get().min(CONVERTER_THREADS));
355	    let built = tokio::runtime::Builder::new_multi_thread().worker_threads(threads).enable_all().build();
356	    let runtime = match built {
357	        Ok(runtime) => runtime,
358	        Err(error) => return SemanticOutcome::unavailable(format!("could not start an async runtime: {error}")),
359	    };
360	    let outcome = runtime.block_on(run_noting(request, None, reads));
361	    if teardown == Teardown::OneShot {
362	        // Dropping the runtime waits for its threads to wind down.
363	        std::mem::forget(runtime);
364	    }
