395	/// [`run`], the linked checker noting what it reads in `reads` ([`kept`]).
396	async fn run_noting(
397	    request: SemanticRequest,
398	    programs: Option<usize>,
399	    reads: Option<Arc<kept::Reads>>,
400	) -> SemanticOutcome {
401	    if request.targets.iter().all(|target| target.exports.is_empty()) {
402	        return group_by_file(&request).0;
403	    }
404	    let files = group_by_file(&request).2.len();
405	    let programs = programs.unwrap_or_else(|| CHECKER_PROGRAMS.min(files.div_ceil(MIN_FILES_PER_PROGRAM))).max(1);
406	    let checker = match Backend::start_noting(&request.project_root, programs, reads) {
407	        Ok(checker) => checker,
408	        Err(reason) => return SemanticOutcome::unavailable(reason),
409	    };
410	    let outcome = answer_with(&checker, &request).await;
411	    checker.shutdown().await;
412	    outcome
413	}
