420	/// Answers the request's targets with a checker that is already running: one snapshot of as many programs rooted at
421	/// their files as the checker answers at once ([`Backend::parallel_programs`]), released once they are answered.
422	async fn answer_with(checker: &Backend, request: &SemanticRequest) -> SemanticOutcome {
423	    let files = root_files(request);
424	    if files.is_empty() {
425	        return group_by_file(request).0;
426	    }
427	    let started = std::time::Instant::now();
428	    let tsconfig = request.tsconfig.as_ref().map(|path| path.as_str());
429	    let count = checker.parallel_programs();
430	    let record = request.record_to.is_some();
431	    let opened = Rpc::open_programs(checker.client(), request.request_timeout, tsconfig, &files, record, count).await;
432	    let programs: Vec<Arc<Rpc>> = match opened {
433	        Ok(programs) => programs.into_iter().map(Arc::new).collect(),
434	        Err(error) => return SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")),
435	    };
436	    answer_opened(programs, request, &files, started).await
437	}
