439	/// Answers the request's targets over `programs`, opened for it at `started`, and releases them as its teardown says.
440	async fn answer_opened(
441	    programs: Vec<Arc<Rpc>>,
442	    request: &SemanticRequest,
443	    files: &[String],
444	    started: std::time::Instant,
445	) -> SemanticOutcome {
446	    tracing::debug!(
447	        program_ms = started.elapsed().as_millis() as u64,
448	        programs = programs.len(),
449	        "semantic program built"
450	    );
451	    let answered = answer_on(&programs, request, files).await;
452	    match request.teardown {
453	        Teardown::Session => {
454	            if let Some(first) = programs.first() {
455	                first.release().await;
456	            }
457	        }
458	        // The checker's shutdown, next, takes the snapshot down with it.
459	        Teardown::OneShot => std::mem::forget(programs),
460	    }
461	    answered.unwrap_or_else(|error| SemanticOutcome::unavailable(format!("the checker stopped answering: {error}")))
462	}
