464	/// Answers the request's targets on a snapshot whose programs are each rooted at `files` ([`root_files`]), one session
465	/// bound to each: a file is answered by one of them, the `n`th file by the `n % programs.len()`th. Each program has its
466	/// checker and its handles, so each has its own [`Converter`]; since every program holds the same files, each answers
467	/// a component as any other would, and the output does not depend on how the files are shared out. The snapshot is
468	/// left as it is, for the caller to keep or release.
469	async fn answer_on(
470	    programs: &[Arc<Rpc>],
471	    request: &SemanticRequest,
472	    files: &[String],
473	) -> Result<SemanticOutcome, CallError> {
474	    let (mut outcome, by_file, order) = group_by_file(request);
475	    let mut answered = session(programs, request, files, &by_file, &order).await?;
476	    outcome.diagnostics.append(&mut answered.diagnostics);
477	    outcome.components.append(&mut answered.components);
478	    outcome.fallbacks.append(&mut answered.fallbacks);
479	    Ok(outcome)
480	}
