482	async fn session(
483	    programs: &[Arc<Rpc>],
484	    request: &SemanticRequest,
485	    files: &[String],
486	    by_file: &FxHashMap<&Utf8Path, Vec<&Target>>,
487	    order: &[&Utf8Path],
488	) -> Result<SemanticOutcome, CallError> {
489	    let started = std::time::Instant::now();
490	    let Some(rpc) = programs.first() else { return Ok(SemanticOutcome::default()) };
491	    let converters: Vec<Converter> =
492	        programs.iter().map(|program| Converter::new(program.clone(), request.reverse_queries)).collect();
493	    let interner = Arc::new(PropInterner::default());
494	    // The files in order; each worker takes the next one when it is done with its last, so a program whose files take
495	    // longer answers fewer of them.
496	    let queue: VecDeque<Vec<Target>> = order
497	        .iter()
498	        .map(|file| by_file.get(file).into_iter().flatten().map(|target| (*target).clone()).collect())
499	        .collect();

